# Change the sheet's today. Validate first so a bad date is a 400 and writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateToday
  next: snapshot
# Keep the figures as they were, so the change can audit the ones it moves.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.sheet.ApplyToday
  govern: [ transaction ]
  next: record-snapshot
# A changed today writes each person's due-total on the day being left (as kept before the change),
# once the new today is set: the sheet as it stood before the move has none.
record-snapshot:
  class: net.officefloor.hq.app.rollup.RecordSnapshot
  govern: [ transaction ]
  next: autoclose
# Once the new today is set, close the periods past their grace days, before the rollup lines.
autoclose:
  class: net.officefloor.hq.app.period.AutoClosePeriods
  govern: [ transaction ]
  next: rollup
# After the change's own lines: a line per person whose figures moved, then the totals if they did.
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
  govern: [ transaction ]
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateToday {
    public void validate(@RequestBody TodayRequest request, Out<LocalDate> today, Out<Actor> actor)
            throws InvalidSheetRequestException {
        String raw = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(raw));
            actor.set(new Actor(request.user()));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + raw);
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Sets the sheet's today; a new today closes every open claim editor, releasing its lock. Keeps the
 *  day being left. */
public class ApplyToday {
    public void apply(@PathVariable("sheetId") String sheetId, @Val LocalDate today, Sheets sheets, Claims claims,
            Out<LeftDay> left) {
        LocalDate leaving = sheets.today(sheetId);
        left.set(new LeftDay(leaving));
        if (!today.equals(leaving)) claims.unlockAll(sheetId);
        sheets.setToday(sheetId, today);
    }
}

